/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import json,hashlib,re
s=Path('reference/session'); p=json.loads((s/'plan-v2.json').read_text())
import jsonschema
jsonschema.Draft7Validator(json.loads(Path('input/plan.schema.json').read_text()),format_checker=jsonschema.FormatChecker()).validate(p)
print('SCHEMA OK; VERSIONS',sorted(x.name for x in s.glob('plan-v*')))
for d in p['decisions']: print(d['id'],d['decision'])
for line in (s/'plan-v2.md').read_text().splitlines():
 if any(k in line for k in ['| revise-fr |','| audit-fr-baseline |','| verify-plan |']) or line.startswith('#'):print(line)
for f in ['evaluations/fr-v1-check.md','execution/fr-baseline-audit-v1.md']:
 print('\\nHASH EVIDENCE',f)
 for l in (s/f).read_text().splitlines():
  if re.search(r'[0-9a-f]{64}',l):print(l)
print('REVIEW EVIDENCE STRUCTURE')
e=json.loads((s/'evaluations/plan-v2/plan-v2-review-evidence.json').read_text());print(e.keys())
for k,v in e.items():
 if 'hash' in k:print(k,json.dumps(v,ensure_ascii=False))
PY"

